// 从媒体集合中随机抽取一个
const keys = Object.keys(meidaSet)
const index = Math.floor(Math.random() * keys.length)
// @ts-ignore
const mediaResources = meidaSet[keys[index]]

// 遍历mdedia集合，让其所有第一个IMG的style = {height: "100%"}
for (let i = 0; i < mediaResources.length; i++) {
    const media = mediaResources[i];
    if (media.type === "IMG") {
        media.style = {
            width: "100%",
            height: "100%",
            objectFit: "cover"
        }
    }
}
mediaResources.push({
    // type: "TITLE",
    fn: (el: any, banner: any) => {
        banner.style.height = '100%'
        banner.parentNode.style.height = '168px'
    }
})


export { mediaResources }
